test("finalized history, retained originals, and byte accounting survive reload", () => {
  const tracker = new ContextPruningTracker(root);
  const first = run(tracker, "first");
  const second = run(tracker, "second");
  const third = run(tracker, "third");
  expect(second.modified).toBe(true);
  expect(third.output).toContain("callId: first");
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  const history = tracker.getHistory();
  expect(history.map(r => r.originalOutput)).toEqual([output, output, output]);
  expect(history.map(r => r.prunedOutput)).toEqual([null, second.output, third.output]);
  const bytes = Buffer.byteLength(output);
  expect(tracker.getStats()).toEqual({
    totalCalls: 3, prunedCalls: 2,
    totalBytesSaved: 2 * bytes - Buffer.byteLength(second.output) - Buffer.byteLength(third.output),
    estimatedContextBytes: [first, second, third].reduce((n, r) => n + Buffer.byteLength(r.output), 0),
  });
  const loaded = new ContextPruningTracker(root);
  loaded.loadHistory(JSON.parse(JSON.stringify(history)));
  expect(loaded.getStats()).toEqual(tracker.getStats());
  expect(run(loaded, "fourth").output).toContain("callId: first");
});

test("rejected shortening creates the newest full baseline and saves no bytes", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "initial");
  const rejected = run(tracker, "rejected", "");
  expect(rejected).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  expect(tracker.getStats()).toEqual({totalCalls: 2, prunedCalls: 0,
