test("unprofitable and failed recovery leave full results", () => {
  for (const [cwd, text] of [[root, "tiny"], [join(root, "missing-file", "..", "bad"), output]]) {
    const tracker = new ContextPruningTracker(root);
    tracker.process("a", "code_search", args, text);
    const finalizer = cwd === root ? recoverablePrune(cwd, "session", "b", text)
